// === DEDUPLICATE v2 - Comparaison multi-criteres + tracabilite (defensif) ===
// Strategies par ordre de priorite :
//   1. DOI identique (strict, high confidence)
//   2. Titre normalise + annee + 1er auteur normalise (strong, medium confidence)
//   3. Titre normalise seul (fallback, low confidence)
//
// Hardening : try/catch global + defensive sur item.json null/undefined.
// Si le code plante, on retourne un item d'erreur structure (au lieu de crasher n8n -> 500).

try {
const items = $input.all();
console.log('[DEDUP v2] Recu ' + items.length + ' items en entree');

// === HELPERS ===
function normalizeTitle(t) {
  return (t || '').toLowerCase()
    .replace(/[^a-z0-9]/g, '')
    .substring(0, 80);
}

// TITRE ENTIER, sans troncature. La troncature a 80 caracteres est une TOLERANCE utile quand
// l'annee et l'auteur corroborent (une source ajoute un sous-titre que l'autre omet). Elle
// devient un piege quand le titre est le SEUL indice : deux tomes d'une meme serie partagent
// leurs 80 premiers caracteres. Plus la corroboration est faible, plus le titre doit etre exact.
function normalizeTitleFull(t) {
  return (t || '').toLowerCase().replace(/[^a-z0-9]/g, '');
}

// === REGLE UNIQUE DE SURVIE D'UN DOUBLON (A7, 2026-08-04) ===
// COPIE MOT POUR MOT de src/notice_merge.py. Les nœuds n8n n'important rien, c'est la seule
// forme de partage possible ; un test croise execute les deux implantations sur le meme jeu et
// exige la meme notice. Ne modifier ici que si l'autre bouge, et inversement.
//
// La question « quelle notice garde-t-on » recevait QUATRE reponses differentes selon le
// chemin. MESURE : deux notices de meme DOI, l'une SANS resume et l'autre avec 106 caracteres,
// rendaient la notice SANS resume, qui tombait ensuite sous le seuil de 50 caracteres du tri
// et sortait « Maybe » sans jamais avoir ete jugee.
// On fusionne, on ne choisit pas : le representant est la notice la plus complete, et il
// recupere de chaque doublon tout champ qui lui manque.
function __ulVide(v) {
  if (v === null || v === undefined) return true;
  if (typeof v === 'string') return v.trim() === '';
  if (Array.isArray(v)) return v.length === 0;
  if (typeof v === 'object') return Object.keys(v).length === 0;
  return false;
}

function __ulOrigines(a) {
  if (Array.isArray(a._merged_sources) && a._merged_sources.length) {
    return a._merged_sources.map(String).filter(function (x) { return x.trim() !== ''; });
  }
  var cles = ['_source', 'source'];
  for (var i = 0; i < cles.length; i++) {
    var v = a[cles[i]];
    if (v && String(v).trim() !== '') return [String(v).trim()];
  }
  return [];
}

function __ulFusionner(a, b) {
  a = a || {}; b = b || {};
  var m = Object.assign({}, a);
  var propres = { _source: 1, source: 1, _merged_sources: 1, abstract: 1, authors: 1 };
  Object.keys(b).forEach(function (cle) {
    if (propres[cle]) return;
    if (__ulVide(m[cle]) && !__ulVide(b[cle])) m[cle] = b[cle];
  });
  var ra = String(a.abstract || ''), rb = String(b.abstract || '');
  m.abstract = (rb.length > ra.length) ? rb : ra;
  var aa = Array.isArray(a.authors) ? a.authors : [];
  var ab = Array.isArray(b.authors) ? b.authors : [];
  m.authors = (ab.length > aa.length) ? ab.slice() : aa.slice();
  var vues = {}, origines = [];
  __ulOrigines(a).concat(__ulOrigines(b)).forEach(function (o) {
    if (!vues[o]) { vues[o] = 1; origines.push(o); }
  });
  if (origines.length) m._merged_sources = origines;
  return m;
}

// Le DOI passe avant le resume : c'est lui qui rattache la notice a une version publiee, et
// sans lui la recuperation du texte integral n'a plus de point d'entree.
function __ulScoreCompletude(a) {
  a = a || {};
  return [String(a.doi || '').trim() ? 1 : 0, String(a.abstract || '').length];
}

function __ulPlusComplet(a, b) {
  var sa = __ulScoreCompletude(a), sb = __ulScoreCompletude(b);
  if (sb[0] !== sa[0]) return sb[0] > sa[0];
  return sb[1] > sa[1];        // a egalite, on garde le PREMIER rencontre
}

function normalizeAuthor(a) {
  if (!a) return '';
  // "Jean Dupont" -> "dupont" ; "Dupont J." -> "dupont" ; ["A. Smith"] -> "smith"
  let s = Array.isArray(a) ? (a[0] || '') : String(a);
  s = s.toLowerCase().replace(/[.,]/g, ' ').trim();
  // Garder le dernier mot (= surname le plus probable)
  const parts = s.split(/\s+/).filter(Boolean);
  return parts.length > 0 ? parts[parts.length - 1] : '';
}

function getYear(item) {
  const y = item.year || item.publication_year || '';
  const m = String(y).match(/\d{4}/);
  return m ? m[0] : '';
}

function getDoi(item) {
  // LA REGLE CANONIQUE, MOT POUR MOT : `src/text_norm.norm_doi` et `parse.ts`.
  // TROIS RETRAITS BORNES, PAS UNE BOUCLE : le texte, puis l'adresse, puis le texte a
  // nouveau. Les deux ordres composes existent (`doi:https://doi.org/x` et
  // `https://doi.org/doi:x`) et un ordre fixe en laissait toujours un passer. Le rognage
  // vient EN PREMIER : sans lui, un espace de tete empeche le retrait de l'adresse.
  // COUT MESURE DE CET ALIGNEMENT AUJOURD'HUI : ZERO. Sur les 376 042 identifiants reels
  // des fichiers du poste, l'ancienne regle et celle-ci rendent la MEME valeur, et aucune
  // notice ne porte le prefixe textuel. C'est de la robustesse : le lecteur Python vient
  // d'etre aligne, les noeuds etaient la derniere moitie en retard, et deux regles pour
  // une seule notion divergent le jour ou l'une est corrigee.
  return String(item.doi || '').trim().toLowerCase()
    .replace(/^doi\s*:\s*/, '')
    .replace(/^https?:\/\/(dx\.)?doi\.org\//, '')
    .replace(/^doi\s*:\s*/, '')
    .trim();
}

function getSourceTag(item) {
  /* LA PROVENANCE SE LIT SOUS SES DEUX NOMS. Le corpus qui arrive du moteur porte
         `source` (lu depuis la balise SO du fichier de recherche), celui qui arrive du
         noeud de recherche porte `_source` : ne lire que le second faisait compter
         « unknown » pour TOUTES les notices du premier chemin. Mesure du 2026-09-04
         sur un fichier reel de 400 notices : 200 clinicaltrials et 200 europepmc,
         comptees 400 unknown. */
      return String(item._source || item.source || 'unknown').toLowerCase();
}

// === DEDUP PASSE 1 : DOI strict ===
const seenDOI = new Map();   // doi -> first_index
const seenTitleYearAuthor = new Map();  // key -> first_index
const seenTitleOnly = new Map();  // titleKey -> first_index

const duplicates = [];  // {index, master_index, strategy, confidence}
const masters = [];      // articles uniques gardes

items.forEach((item, idx) => {
  // Hardening : item.json peut etre null/undefined dans des cas tres edge
  const a = (item && item.json) ? item.json : {};
  const doi = getDoi(a);
  const titleNorm = normalizeTitle(a.title);
  const titleFull = normalizeTitleFull(a.title);
  const year = getYear(a);
  const firstAuthor = normalizeAuthor(a.authors);
  const tyaKey = titleNorm + '|' + year + '|' + firstAuthor;

  // Strategie 1 : DOI
  if (doi) {
    if (seenDOI.has(doi)) {
      duplicates.push({
        index: idx,
        master_index: seenDOI.get(doi),
        strategy: 'doi',
        confidence: 'high',
        key: doi
      });
      return;
    }
    seenDOI.set(doi, idx);
  }

  // Strategie 2 : titre + annee + auteur (si titre + annee + auteur tous presents)
  if (titleNorm && year && firstAuthor) {
    if (seenTitleYearAuthor.has(tyaKey)) {
      duplicates.push({
        index: idx,
        master_index: seenTitleYearAuthor.get(tyaKey),
        strategy: 'title+year+author',
        confidence: 'medium',
        key: tyaKey
      });
      return;
    }
    seenTitleYearAuthor.set(tyaKey, idx);
  }

  // Strategie 3 : titre normalise seul (fallback faible). DEUX durcissements (A7) :
  // le titre doit correspondre ENTIEREMENT, et ni l'annee ni le premier auteur ne doivent
  // CONTREDIRE. Sans eux, « ...part I » (2018, Smith) et « ...part II » (2021, Jones) etaient
  // declares doublons, mesure faite sur ce nœud meme.
  if (titleFull && titleFull.length >= 20) {
    const dejaVu = seenTitleOnly.get(titleFull);
    if (dejaVu !== undefined) {
      const p = (items[dejaVu] && items[dejaVu].json) ? items[dejaVu].json : {};
      const anneeP = getYear(p), auteurP = normalizeAuthor(p.authors);
      const contredit = (year && anneeP && year !== anneeP)
                     || (firstAuthor && auteurP && firstAuthor !== auteurP);
      if (!contredit) {
        duplicates.push({
          index: idx,
          master_index: dejaVu,
          strategy: 'title-only',
          confidence: 'low',
          key: titleFull
        });
        return;
      }
      // Contradiction : ce n'est pas un doublon. On ne reecrit pas la premiere occurrence,
      // qui reste la reference pour les suivantes.
    } else {
      seenTitleOnly.set(titleFull, idx);
    }
  }

  // Pas de doublon -> garde l'article
  masters.push({ index: idx, item: item });
});

// === STATISTIQUES ===
const strategies = { doi: 0, 'title+year+author': 0, 'title-only': 0 };
const confidences = { high: 0, medium: 0, low: 0 };
for (const d of duplicates) {
  strategies[d.strategy] = (strategies[d.strategy] || 0) + 1;
  confidences[d.confidence] = (confidences[d.confidence] || 0) + 1;
}

const sourceCounts = {};
for (const m of masters) {
  const src = getSourceTag(m.item.json);
  sourceCounts[src] = (sourceCounts[src] || 0) + 1;
}

console.log('[DEDUP v2] Resultats :');
console.log('  Items entree : ' + items.length);
console.log('  Uniques gardes : ' + masters.length);
console.log('  Doublons supprimes : ' + duplicates.length);
console.log('  Par strategie : doi=' + (strategies.doi||0) + ' tya=' + (strategies['title+year+author']||0) + ' title=' + (strategies['title-only']||0));
console.log('  Par confidence : high=' + (confidences.high||0) + ' medium=' + (confidences.medium||0) + ' low=' + (confidences.low||0));
console.log('  Par source : ' + JSON.stringify(sourceCounts));

// === OUTPUT ===
// Premier item : enrichi avec les stats globales + rapport detaille
// Tous les items : enrichis avec _deduplication_key, _dedup_strategy, _total_before_dedup, _duplicates_removed
const dedupReport = {
  total_input: items.length,
  total_unique: masters.length,
  total_duplicates: duplicates.length,
  dedup_rate_pct: items.length > 0 ? Math.round(duplicates.length * 100 / items.length) : 0,
  strategies: strategies,
  confidences: confidences,
  by_source: sourceCounts,
  // Liste detaillee des doublons detectes (limite 1000 pour eviter explosion JSON)
  duplicates_detail: duplicates.slice(0, 1000).map(d => ({
    duplicate_title: ((items[d.index] && items[d.index].json && items[d.index].json.title) || '').substring(0, 120),
    master_title: ((items[d.master_index] && items[d.master_index].json && items[d.master_index].json.title) || '').substring(0, 120),
    strategy: d.strategy,
    confidence: d.confidence,
    key_excerpt: String(d.key).substring(0, 60)
  }))
};

// Hardening : utilise m.item.json || {} pour eviter crash si jamais null
const firstMasterIdx = masters.length > 0 ? masters[0].index : -1;
// A7 : ON FUSIONNE, ON NE CHOISIT PAS. Le representant du groupe est la notice la plus
// complete, et il recupere de chaque doublon tout champ qui lui manque. Auparavant la
// PREMIERE notice rencontree gagnait, resume absent compris.
const enfants = {};
for (const d of duplicates) {
  if (!enfants[d.master_index]) enfants[d.master_index] = [];
  enfants[d.master_index].push(d.index);
}
return masters.map(m => {
  const membres = [m.index].concat(enfants[m.index] || []);
  let rep = membres[0];
  for (let k = 1; k < membres.length; k++) {
    const cand = (items[membres[k]] && items[membres[k]].json) ? items[membres[k]].json : {};
    const actuel = (items[rep] && items[rep].json) ? items[rep].json : {};
    if (__ulPlusComplet(actuel, cand)) rep = membres[k];
  }
  let src = Object.assign({}, (items[rep] && items[rep].json) ? items[rep].json : {});
  for (const i of membres) {
    if (i === rep) continue;
    src = __ulFusionner(src, (items[i] && items[i].json) ? items[i].json : {});
  }
  return {
    json: Object.assign({}, src, {
      _deduplication_key: getDoi(src) || normalizeTitle(src.title),
      _dedup_group_size: membres.length,
      _total_before_dedup: items.length,
      _duplicates_removed: duplicates.length,
      _dedup_report: m.index === firstMasterIdx ? dedupReport : undefined
    })
  };
});

} catch (err) {
  // Si quoi que ce soit plante dans le code dedup, on retourne un item d'erreur structure
  // au lieu de laisser n8n planter avec HTTP 500. Permet a l'UI d'afficher un message utile.
  console.log('[DEDUP v2] ERREUR FATALE : ' + err.message);
  console.log('[DEDUP v2] Stack : ' + (err.stack || 'N/A'));
  return [{ json: {
    error: 'Dedup v2 plantage : ' + err.message,
    error_stack: (err.stack || '').substring(0, 1000),
    _dedup_failed: true,
    _input_count: (typeof items !== 'undefined' && items) ? items.length : 0
  }}];
}
